package com.junliang.midibridge;
import java.io.*;
import java.util.*;

/** Fixtures cover musical timing, malformed files and continuation identity across gestures. */
public final class MidiFileChecks {
 private static int checks;
 private static void eq(long actual,long expected,String label){checks++;if(actual!=expected)throw new AssertionError(label+": "+actual+" != "+expected);}
 private static void ok(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 private static void vlq(ByteArrayOutputStream out,long n){int v=(int)(n&127);while((n>>=7)>0)v=(v<<8)|((int)(n&127)|128);while(true){out.write(v&255);if((v&128)==0)break;v>>>=8;}}
 private static void event(ByteArrayOutputStream out,int delta,int... bytes){vlq(out,delta);for(int b:bytes)out.write(b);}
 private static byte[] file(int format,int division,byte[]... tracks)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(out);d.writeInt(0x4d546864);d.writeInt(6);d.writeShort(format);d.writeShort(tracks.length);d.writeShort(division);for(byte[] tr:tracks){d.writeInt(0x4d54726b);d.writeInt(tr.length);d.write(tr);}return out.toByteArray();}
 private static SmfFile parse(ByteArrayOutputStream tr)throws IOException{return SmfFile.read(file(0,480,tr.toByteArray()));}
 private static void rejects(byte[] bytes,String label){checks++;try{SmfFile.read(bytes);}catch(IOException expected){return;}throw new AssertionError(label);}
 public static void main(String[] args)throws Exception{run();}
 public static void run()throws Exception{checks=0;
  ByteArrayOutputStream tr=new ByteArrayOutputStream();event(tr,0,0xff,0x51,3,7,0xa1,0x20);event(tr,17,0x90,60,100);event(tr,0,64,90);event(tr,463,0x80,60,0);event(tr,0,64,0);event(tr,0,0xff,0x51,3,0x0f,0x42,0x40);event(tr,240,0x90,67,110);event(tr,240,0x90,67,0);event(tr,480,0xff,0x2f,0);
  SmfFile song=parse(tr);eq(song.notes.size(),3,"chord plus melody");eq(song.notes.get(0).startUs,17708,"off-grid onset preserved");eq(song.notes.get(1).startUs,17708,"chord same onset");eq(song.notes.get(0).endUs,500000,"PPQ duration");eq(song.notes.get(2).startUs,1000000,"tempo-map onset");eq(song.notes.get(2).endUs,1500000,"tempo-map release");eq(song.durationUs,2500000,"trailing rest retained");eq(song.tempoChanges,2,"tempo count");
  MidiScore score=MidiScore.build(song,null,0,0,true,100);eq(score.holds.get(0).startMs,18,"millisecond rounding without grid");eq(score.durationMs,2500,"end rest retained in score");eq(MidiScore.maxPolyphony(score.holds),2,"chord polyphony");MidiScore twice=MidiScore.build(song,null,0,0,true,200);eq(twice.holds.get(0).startMs,9,"speed scale");eq(twice.holds.get(2).startMs,500,"tempo map speed scale");
  tr.reset();event(tr,0,0x90,60,100);event(tr,120,0xb0,64,127);event(tr,120,0x80,60,0);event(tr,240,0xb0,64,0);event(tr,0,0xff,0x2f,0);song=parse(tr);eq(song.notes.get(0).endUs,500000,"sustain extends to pedal up");
  tr.reset();event(tr,0,0x90,60,100);event(tr,0,60,80);event(tr,120,0x80,60,0);event(tr,120,60,0);event(tr,0,0xff,0x2f,0);song=parse(tr);eq(song.notes.size(),2,"FIFO overlapping same pitch");eq(song.notes.get(0).endUs,125000,"first overlap off");eq(song.notes.get(1).endUs,250000,"second overlap off");score=MidiScore.build(song,null,0,0,true,100);eq(score.holds.size(),1,"same-key simultaneous merged");eq(score.holds.get(0).endMs,250,"merged final off");
  tr.reset();event(tr,0,0x90,36,100);event(tr,240,0x90,48,90);event(tr,240,0x80,48,0);event(tr,240,0x80,36,0);event(tr,0,0xff,0x2f,0);score=MidiScore.build(parse(tr),null,0,0,true,100);eq(score.holds.size(),2,"fold collision retrigger");eq(score.holds.get(0).endMs,249,"release gap before retrigger");eq(score.holds.get(1).endMs,750,"old overlap still held at last off");eq(score.events.get(1).ms,249,"release before new attack");eq(MidiScore.maxPolyphony(score.holds),1,"physical key never overlaps itself");
  tr.reset();event(tr,0,0x90,61,100);event(tr,0,0x99,60,100);event(tr,480,0x80,61,0);event(tr,0,0x89,60,0);event(tr,0,0xff,0x2f,0);song=parse(tr);eq(MidiScore.build(song,null,0,0,true,100).holds.size(),0,"black notes skip and drums skip");score=MidiScore.build(song,null,0,1,true,100);eq(score.holds.get(0).key,8,"C sharp up D");eq(score.corrected,1,"correction reported");eq(score.skipped,1,"drums reported");eq(MidiScore.build(song,null,0,2,true,100).holds.get(0).key,7,"C sharp down C");
  for(int n=0;n<128;n++)for(int mode=0;mode<3;mode++){int ix=NoteMap.index(n,0,true,mode);if(mode>0){ok(ix>=0&&ix<21,"all notes map by octave");int adjusted=n;int pc=n%12;if(pc==1||pc==3||pc==6||pc==8||pc==10)adjusted+=mode==1?1:-1;eq(NoteMap.NOTES[ix]%12,adjusted%12,"pitch class preserved after correction");}}
  ByteArrayOutputStream tempo=new ByteArrayOutputStream(),voice=new ByteArrayOutputStream();event(tempo,0,0xff,3,4,'T','e','m','p');event(tempo,240,0xff,0x51,3,0x0f,0x42,0x40);event(tempo,240,0xff,0x2f,0);event(voice,0,0x90,60,100);event(voice,480,0x80,60,0);event(voice,0,0xff,0x2f,0);song=SmfFile.read(file(1,480,tempo.toByteArray(),voice.toByteArray()));eq(song.notes.get(0).endUs,750000,"format1 tempo in conductor track");ok(song.trackNames[0].equals("Temp"),"track name");eq(MidiScore.build(song,new boolean[]{true,false},0,0,true,100).holds.size(),0,"track exclusion");
  tr.reset();event(tr,0,0x90,60,100);event(tr,1000,0x80,60,0);event(tr,0,0xff,0x2f,0);song=SmfFile.read(file(0,(-25&255)<<8|40,tr.toByteArray()));eq(song.notes.get(0).endUs,1000000,"SMPTE25");song=SmfFile.read(file(0,(-29&255)<<8|100,tr.toByteArray()));eq(song.notes.get(0).endUs,333667,"SMPTE drop frame29.97");
  tr.reset();event(tr,0,0x90,60,100);event(tr,480,0xff,0x2f,0);song=parse(tr);eq(song.unclosedNotes,1,"missing off warning");eq(song.notes.get(0).endUs,500000,"missing off bounded by song end");
  tr.reset();event(tr,0,0x90,60,100);event(tr,120,0xb0,123,0);event(tr,0,0xff,0x2f,0);eq(parse(tr).notes.get(0).endUs,125000,"all notes off");
  rejects(new byte[]{1,2,3},"truncated header");rejects(file(2,480,new byte[0]),"format2 rejected");rejects(file(0,0,new byte[0]),"zero PPQ");rejects(file(0,(-28&255)<<8|40,new byte[0]),"bad SMPTE fps");rejects(file(0,480,new byte[]{0,60,100}),"missing running status");rejects(file(0,480,new byte[]{0,(byte)0x90,60,(byte)200}),"invalid MIDI data");rejects(file(0,480,new byte[]{(byte)0x80,(byte)0x80,(byte)0x80,(byte)0x80,0}),"invalid VLQ");rejects(file(0,480,new byte[]{0,(byte)0xff,0x51,3,0,0,0}),"zero tempo");rejects(file(0,480,new byte[]{0,(byte)0xf0,10,1}),"truncated sysex");
  rejects(new byte[SmfFile.MAX_BYTES+1],"file size bounded before parse");tr.reset();event(tr,0x0fffffff,0x90,60,100);rejects(file(0,480,tr.toByteArray()),"six-hour limit at event");tr.reset();event(tr,0,0x90,60,100);event(tr,0x0fffffff,0xff,0x2f,0);rejects(file(0,480,tr.toByteArray()),"six-hour limit at trailing end");
  tr.reset();for(int i=0;i<=SmfFile.MAX_EVENTS;i++)event(tr,0,0xff,1,0);rejects(file(0,480,tr.toByteArray()),"event count bounded");byte[][] manyTracks=new byte[SmfFile.MAX_TRACKS+1][];Arrays.fill(manyTracks,new byte[0]);rejects(file(1,480,manyTracks),"track count bounded");
  tr.reset();event(tr,0,0xf0,2,1,0xf7);event(tr,0,0x90,60,100);event(tr,480,0x80,60,0);event(tr,0,0xff,0x2f,0);eq(parse(tr).notes.size(),1,"sysex skipped");byte[] valid=file(0,480,tr.toByteArray());for(int cut=0;cut<valid.length;cut++)rejects(Arrays.copyOf(valid,cut),"truncation at every byte "+cut);
  // Chunked long notes retain one pointer identity; dense sequences split before overflow.
  ArrayList<MidiScore.Gate> gates=new ArrayList<>();gates.add(new MidiScore.Gate(0,0,100,17,550));gates.add(new MidiScore.Gate(1,1,100,33,73));gates.add(new MidiScore.Gate(2,2,100,310,650));validateTimeline(gates,20);
  gates.clear();for(int i=0;i<80;i++)gates.add(new MidiScore.Gate(i,i%7,100,i*7,i*7+3));validateTimeline(gates,4);
  gates.clear();for(int i=0;i<12;i++)gates.add(new MidiScore.Gate(i,i,100,0,800));eq(MidiScore.maxPolyphony(gates),12,"over-limit chord detected");checks++;try{new GestureTimeline(gates).slice(0,100,10);throw new AssertionError("concurrent pointer overflow accepted");}catch(IllegalArgumentException expected){}
  System.out.println("PASS: "+checks+" MIDI file/timeline assertions");
 }
 private static void validateTimeline(List<MidiScore.Gate> gates,int max){GestureTimeline timeline=new GestureTimeline(gates);Map<Integer,Long> starts=new HashMap<>(),ends=new HashMap<>();Set<Integer> held=new HashSet<>();long cursor=0;int slices=0;
  while(timeline.nextStart(cursor)!=Long.MAX_VALUE){cursor=Math.max(cursor,timeline.nextStart(cursor));GestureTimeline.Slice slice=timeline.slice(cursor,cursor+100,max);ok(slice.end>cursor,"forward slice progress");ok(slice.parts.size()<=max,"stroke budget includes carry");Set<Integer> next=new HashSet<>();for(GestureTimeline.Part p:slice.parts){ok(p.duration>=1,"positive stroke duration");if(held.contains(p.gate.id))eq(p.offset,0,"continuation starts at zero");else{ok(!starts.containsKey(p.gate.id),"single down per pointer");starts.put(p.gate.id,cursor+p.offset);}if(p.continues)next.add(p.gate.id);else ends.put(p.gate.id,cursor+p.offset+p.duration);}held=next;cursor=slice.end;if(++slices>1000)throw new AssertionError("slice loop");}
  eq(held.size(),0,"all fingers finally released");for(MidiScore.Gate g:gates){eq(starts.get(g.id),g.startMs,"exact onset through segmentation");eq(ends.get(g.id),g.endMs,"exact off through segmentation");}
 }
}
